import { createClient } from "@/lib/supabase/server";
import { FolderKanban, Receipt } from "lucide-react";
import Link from "next/link";

export default async function PortalDashboard() {
  const supabase = await createClient();
  const {
    data: { user }
  } = await supabase.auth.getUser();

  // Fetch dashboard data — RLS auto-scopes to this user.
  // (Messages tile dropped in Phase 1 — Intercom owns chat now;
  // tickets/work-orders tile will land in Phase 3.)
  const [projectsRes, invoicesRes] = await Promise.all([
    supabase.from("projects").select("id,title,status").limit(5),
    supabase
      .from("invoices")
      .select("id,project_id,amount_cents,currency,status,due_date")
      .in("status", ["open", "overdue"])
      .limit(5)
  ]);

  const projects = projectsRes.data ?? [];
  const openInvoices = invoicesRes.data ?? [];
  void user;

  return (
    <div className="space-y-8">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">
          Welcome back{user?.user_metadata?.full_name ? `, ${user.user_metadata.full_name}` : ""}.
        </h1>
        <p className="text-muted-foreground mt-1">Here&apos;s what&apos;s open.</p>
      </header>

      <div className="grid sm:grid-cols-2 gap-4">
        <DashboardTile
          href="/portal/projects"
          icon={<FolderKanban className="h-5 w-5" />}
          value={projects.filter((p) => p.status === "active").length}
          label="Active projects"
        />
        <DashboardTile
          href="/portal/invoices"
          icon={<Receipt className="h-5 w-5 text-accent" />}
          value={openInvoices.length}
          label="Open invoices"
        />
      </div>

      <section>
        <h2 className="font-display text-xl font-semibold mb-3">Recent projects</h2>
        {projects.length === 0 ? (
          <EmptyState
            title="No projects yet"
            body="When we start working together, projects show up here with files and invoices."
          />
        ) : (
          <ul className="rounded-lg border border-border divide-y divide-border">
            {projects.map((p) => (
              <li key={p.id} className="p-4 flex items-center justify-between hover:bg-muted/40">
                <div>
                  <p className="font-medium">{p.title}</p>
                  <p className="text-xs uppercase tracking-wider text-muted-foreground mt-0.5">
                    {p.status}
                  </p>
                </div>
                <Link
                  href={`/portal/projects/${p.id}`}
                  className="text-sm font-medium text-primary hover:underline"
                >
                  Open →
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

function DashboardTile({
  href,
  icon,
  value,
  label
}: {
  href: string;
  icon: React.ReactNode;
  value: number;
  label: string;
}) {
  return (
    <Link
      href={href}
      className="rounded-xl border border-border bg-card p-5 hover:shadow-glow hover:border-primary/40 transition-all"
    >
      <div className="flex items-center justify-between mb-3 text-muted-foreground">
        {icon}
      </div>
      <p className="font-display text-3xl font-bold">{value}</p>
      <p className="text-sm text-muted-foreground mt-1">{label}</p>
    </Link>
  );
}

function EmptyState({ title, body }: { title: string; body: string }) {
  return (
    <div className="rounded-xl border border-dashed border-border p-8 text-center">
      <p className="font-semibold">{title}</p>
      <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">{body}</p>
    </div>
  );
}

import Link from "next/link";
import { createClient } from "@/lib/supabase/server";

export default async function ProjectsListPage() {
  const supabase = await createClient();
  const { data: projects } = await supabase
    .from("projects")
    .select("id,title,description,status,started_at,delivered_at")
    .order("created_at", { ascending: false });

  return (
    <div className="space-y-6">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">
          Projects
        </h1>
        <p className="text-muted-foreground mt-1">
          All your work in one place.
        </p>
      </header>

      {!projects || projects.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border p-10 text-center">
          <p className="font-semibold">No projects yet</p>
          <p className="text-sm text-muted-foreground mt-1">
            New work shows up here once we start an engagement.
          </p>
        </div>
      ) : (
        <ul className="rounded-lg border border-border divide-y divide-border">
          {projects.map((p) => (
            <li
              key={p.id}
              className="p-4 flex items-start justify-between gap-4"
            >
              <div>
                <Link
                  href={`/portal/projects/${p.id}`}
                  className="font-semibold hover:text-primary"
                >
                  {p.title}
                </Link>
                {p.description && (
                  <p className="text-sm text-muted-foreground mt-1 max-w-xl">
                    {p.description}
                  </p>
                )}
                <p className="text-xs uppercase tracking-wider text-muted-foreground mt-2">
                  {p.status}
                </p>
              </div>
              <Link
                href={`/portal/projects/${p.id}`}
                className="shrink-0 text-sm font-medium text-primary hover:underline"
              >
                Open →
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * Portal: work-order tickets list (Phase 3).
 *
 * Owner-scoped via RLS — `created_by = auth.uid()` is the only policy on the
 * `work_orders` table for non-admin users, so this `select(*)` is naturally
 * filtered.
 */
import Link from "next/link";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { formatCurrency } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { NewWorkOrderDialog } from "@/components/portal/NewWorkOrderDialog";
import type { WorkOrderStatus } from "@/lib/database.types";

export const dynamic = "force-dynamic";

function statusTone(status: string): "indigo" | "amber" | "neutral" {
  switch (status) {
    case "open":
    case "quoted":
      return "amber";
    case "accepted":
    case "in_progress":
      return "indigo";
    case "delivered":
    case "closed":
      return "neutral";
    case "cancelled":
      return "neutral";
    default:
      return "neutral";
  }
}

const SERVICE_LABELS: Record<string, string> = {
  logo: "Logo",
  website_update: "Website update",
  data_export: "Data export",
  consulting: "Consulting",
  other: "Other"
};

export default async function TicketsPage() {
  const supabase = await createClient();
  const {
    data: { user }
  } = await supabase.auth.getUser();
  if (!user) redirect("/login?next=/portal/tickets");

  const { data: tickets, error } = await supabase
    .from("work_orders")
    .select(
      "id,title,service_type,status,created_at,quoted_amount_cents,invoice_id"
    )
    .order("created_at", { ascending: false });

  return (
    <div className="space-y-6">
      <header className="flex items-start justify-between gap-4">
        <div>
          <h1 className="font-display text-3xl font-bold tracking-tight">Tickets</h1>
          <p className="text-muted-foreground mt-1">
            Open a ticket for any new design, build, or consulting work.
          </p>
        </div>
        <NewWorkOrderDialog />
      </header>

      {error && (
        <p className="rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">
          Couldn&apos;t load tickets: {error.message}
        </p>
      )}

      {!tickets || tickets.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border p-10 text-center">
          <p className="font-semibold">No tickets yet</p>
          <p className="text-muted-foreground mt-1 text-sm">
            Hit &ldquo;New ticket&rdquo; above to send me your first one.
          </p>
        </div>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-border">
          <table className="w-full text-sm">
            <caption className="sr-only">Your work-order tickets</caption>
            <thead className="bg-muted/40 text-left text-xs uppercase tracking-wider text-muted-foreground">
              <tr>
                <th scope="col" className="p-3">
                  Title
                </th>
                <th scope="col" className="p-3">
                  Service
                </th>
                <th scope="col" className="p-3">
                  Status
                </th>
                <th scope="col" className="p-3">
                  Quote
                </th>
                <th scope="col" className="p-3">
                  Opened
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {tickets.map((t) => (
                <tr key={t.id} className="hover:bg-muted/30 transition-colors">
                  <td className="p-3">
                    <Link
                      href={`/portal/tickets/${t.id}`}
                      className="font-semibold underline-offset-4 hover:underline rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                    >
                      {t.title}
                    </Link>
                  </td>
                  <td className="p-3 text-muted-foreground">
                    {SERVICE_LABELS[t.service_type] ?? t.service_type}
                  </td>
                  <td className="p-3">
                    <Badge tone={statusTone(t.status as WorkOrderStatus)} aria-label={`Status: ${t.status.replace(/_/g, " ")}`}>
                      {t.status.replace(/_/g, " ")}
                    </Badge>
                  </td>
                  <td className="p-3">
                    {t.quoted_amount_cents
                      ? formatCurrency(t.quoted_amount_cents)
                      : <span className="text-muted-foreground">—</span>}
                  </td>
                  <td className="p-3 text-muted-foreground">
                    {new Date(t.created_at).toLocaleDateString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { createClient } from "@/lib/supabase/server";

export default async function FilesPage() {
  const supabase = await createClient();
  const { data: files } = await supabase
    .from("project_files")
    .select(
      "id,filename,mime,size_bytes,uploaded_at,retention_until,project_id,storage_path",
    )
    .order("uploaded_at", { ascending: false });

  return (
    <div className="space-y-6">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">
          Files
        </h1>
        <p className="text-muted-foreground mt-1">
          All deliverables. Stored encrypted, kept for 3 years from upload.
        </p>
      </header>

      {!files || files.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border p-10 text-center">
          <p className="font-semibold">No files yet</p>
        </div>
      ) : (
        <ul className="rounded-lg border border-border divide-y divide-border">
          {files.map((f) => (
            <li
              key={f.id}
              className="p-4 grid grid-cols-[1fr_auto] items-center gap-3"
            >
              <div>
                <p className="font-medium">{f.filename}</p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {f.mime ?? "file"} ·{" "}
                  {f.size_bytes
                    ? `${(f.size_bytes / 1024).toFixed(1)} KB`
                    : "—"}{" "}
                  · retained until{" "}
                  {new Date(f.retention_until).toLocaleDateString()}
                </p>
              </div>
              <form action={`/api/files/${f.id}/download`} method="post">
                <button
                  type="submit"
                  className="text-sm font-medium text-primary hover:underline"
                >
                  Download →
                </button>
              </form>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

