import Link from "next/link";
import { createAdminClient } from "@/lib/supabase/server";
import { isAdminEmail } from "@/lib/utils";
import { InviteUserForm } from "@/components/admin/InviteUserForm";

export default async function AdminUsersPage() {
  const supabase = createAdminClient();
  const { data: profiles } = await supabase
    .from("profiles")
    .select("id,full_name,company,created_at")
    .order("created_at", { ascending: false });

  const adminIds = new Set<string>();
  try {
    const { data: usersList } = await supabase.auth.admin.listUsers({ page: 1, perPage: 200 });
    for (const user of usersList?.users ?? []) {
      if (isAdminEmail(user.email)) adminIds.add(user.id);
    }
  } catch (e) {
    console.warn("[admin users] auth.admin.listUsers failed:", e);
  }

  return (
    <div className="space-y-6">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">Users</h1>
        <p className="text-muted-foreground mt-1">Everyone with a portal account.</p>
      </header>

      <section className="rounded-lg border border-border bg-card p-6">
        <h2 className="font-display text-xl font-semibold mb-1">Invite a user</h2>
        <p className="text-sm text-muted-foreground mb-4">
          Sends a Supabase invite email. The profile row is created when they accept.
        </p>
        <InviteUserForm />
      </section>

      {!profiles || profiles.length === 0 ? (
        <p className="rounded-lg border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
          No users yet. The first user is created on first magic-link login.
        </p>
      ) : (
        <ul className="rounded-lg border border-border divide-y divide-border">
          {profiles.map((p) => (
            <li key={p.id} className="p-4 flex items-center justify-between">
              <div>
                <p className="font-medium">{p.full_name ?? "(no name set)"}</p>
                <p className="text-xs text-muted-foreground">{p.company ?? "—"}</p>
                {adminIds.has(p.id) && (
                  <span className="inline-block mt-1 text-[10px] uppercase tracking-wider font-bold bg-accent/15 text-accent rounded px-1.5 py-0.5">
                    Admin
                  </span>
                )}
              </div>
              <Link
                href={`/admin/users/${p.id}`}
                className="text-sm font-medium text-primary hover:underline"
              >
                Edit →
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { createAdminClient } from "@/lib/supabase/server";
import { formatCurrency } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { NewInvoiceDialog } from "@/components/admin/NewInvoiceDialog";
import { AdminMarkPaidButton } from "@/components/admin/AdminMarkPaidButton";

export const dynamic = "force-dynamic";

export default async function AdminInvoicesPage() {
  const supabase = createAdminClient();
  const [{ data: invoices }, { data: profilesData }, { data: projects }] = await Promise.all([
    supabase
      .from("invoices")
      .select(
        "id,project_id,amount_cents,currency,status,due_date,paid_at,stripe_invoice_id,hosted_invoice_url,created_at"
      )
      .order("created_at", { ascending: false })
      .limit(200),
    supabase.from("profiles").select("id,full_name,company").limit(500),
    supabase.from("projects").select("id,title,owner_user_id").limit(500)
  ]);

  // Resolve auth emails for the picker — bulk via auth admin.
  let usersForPicker: Array<{ id: string; label: string }> = [];
  try {
    const { data: usersList } = await supabase.auth.admin.listUsers({ page: 1, perPage: 200 });
    const profilesById = new Map((profilesData ?? []).map((p) => [p.id, p]));
    usersForPicker = (usersList?.users ?? []).map((u) => {
      const prof = profilesById.get(u.id);
      const label = prof?.full_name
        ? `${prof.full_name} <${u.email ?? "?"}>`
        : (u.email ?? u.id);
      return { id: u.id, label };
    });
  } catch (e) {
    // Picker will fall back to empty -- "no users yet" message.
    console.warn("[admin invoices] auth.admin.listUsers failed:", e);
  }

  const projectOptions = (projects ?? []).map((p) => ({
    id: p.id,
    label: p.title,
    ownerUserId: p.owner_user_id
  }));

  const open = invoices?.filter((i) => i.status === "open" || i.status === "overdue") ?? [];

  return (
    <div className="space-y-6">
      <header className="flex items-start justify-between gap-4">
        <div>
          <h1 className="font-display text-3xl font-bold tracking-tight">Invoices</h1>
          <p className="text-muted-foreground mt-1">
            Open: <strong>{open.length}</strong> ·{" "}
            Open total: <strong>{formatCurrency(open.reduce((s, i) => s + i.amount_cents, 0))}</strong>
          </p>
        </div>
        <NewInvoiceDialog users={usersForPicker} projects={projectOptions} />
      </header>

      {!invoices || invoices.length === 0 ? (
        <p className="rounded-lg border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
          No invoices yet.
        </p>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-border">
          <table className="w-full text-sm">
            <thead className="bg-muted/40 text-left text-xs uppercase tracking-wider text-muted-foreground">
              <tr>
                <th className="p-3">Invoice</th>
                <th className="p-3">Amount</th>
                <th className="p-3">Status</th>
                <th className="p-3">Due</th>
                <th className="p-3">Stripe</th>
                <th className="p-3 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {invoices.map((inv) => (
                <tr key={inv.id}>
                  <td className="p-3 font-mono text-xs">{inv.id.slice(0, 8)}…</td>
                  <td className="p-3 font-semibold">{formatCurrency(inv.amount_cents, inv.currency)}</td>
                  <td className="p-3">
                    <Badge tone={inv.status === "paid" ? "neutral" : inv.status === "overdue" ? "amber" : "indigo"}>
                      {inv.status}
                    </Badge>
                  </td>
                  <td className="p-3 text-xs text-muted-foreground">
                    {inv.due_date ? new Date(inv.due_date).toLocaleDateString() : "—"}
                  </td>
                  <td className="p-3 text-xs">
                    {inv.hosted_invoice_url ? (
                      <a
                        href={inv.hosted_invoice_url}
                        target="_blank"
                        rel="noreferrer"
                        className="text-primary hover:underline"
                      >
                        View Stripe invoice →
                      </a>
                    ) : inv.stripe_invoice_id ? (
                      <a
                        href={`https://dashboard.stripe.com/invoices/${inv.stripe_invoice_id}`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-primary hover:underline"
                      >
                        dashboard →
                      </a>
                    ) : (
                      <span className="text-muted-foreground">draft (no Stripe id)</span>
                    )}
                  </td>
                  <td className="p-3 text-right">
                    {inv.status !== "paid" && <AdminMarkPaidButton invoiceId={inv.id} />}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { createAdminClient } from "@/lib/supabase/server";

export default async function AdminBookingsPage() {
  const supabase = createAdminClient();
  const { data: bookings, error } = await supabase
    .from("bookings")
    .select("*")
    .order("scheduled_at", { ascending: false })
    .limit(100);

  // Schema is now unified — surface bookings errors honestly instead of
  // masking them behind a fallback read against the leads table.
  if (error) {
    console.error("[admin/bookings] supabase error:", error.message ?? error);
  }
  const rows = bookings ?? [];

  return (
    <div className="space-y-6">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">Bookings</h1>
        <p className="text-muted-foreground mt-1">Discovery calls scheduled via the landing lightbox.</p>
      </header>

      {error ? (
        <p className="rounded-lg border border-destructive/40 bg-destructive/5 p-4 text-sm text-destructive">
          Couldn&rsquo;t load bookings. Check Supabase connectivity — see server logs for details.
        </p>
      ) : null}

      {rows.length === 0 ? (
        <p className="rounded-lg border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
          No bookings yet. As soon as someone books through Calendly, they appear here.
        </p>
      ) : (
        <ul className="rounded-lg border border-border divide-y divide-border">
          {rows.map((b) => (
            <li key={b.id} className="p-4 flex justify-between items-start">
              <div>
                <p className="font-semibold">{b.name ?? b.email}</p>
                <p className="text-xs text-muted-foreground">{b.email}</p>
                {b.notes && <p className="text-sm mt-1 max-w-xl">{b.notes}</p>}
              </div>
              <div className="text-right">
                <p className="text-sm font-medium">{new Date(b.scheduled_at).toLocaleString()}</p>
                <p className="text-xs uppercase tracking-wider text-muted-foreground">{b.status}</p>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

